// Errors arrive from the API in English; show them in the viewer's language when the message is known.
export function translateError(lang, message) {
  if (typeof message !== 'string' || lang === 'en') return message;
  const tries = /^That code does not match\. (\d+) tries left\.$/.exec(message);
  if (tries) return translate(lang, 'err.codeMismatch', { n: tries[1] });
  const key = Object.keys(dict.en).find(k => k.startsWith('err.') && dict.en[k] === message);
  return key ? translate(lang, key) : message;
}

export const translate = (lang, key, vars = {}) => String(dict[lang]?.[key] ?? dict.en[key] ?? key).replace(/\{(\w+)\}/g, (_, k) => vars[k] ?? '');

const I18n = createContext({ lang: 'en', t: (k, v) => translate('en', k, v), setLang: () => {}, scale: 1, setScale: () => {} });

// Language + text size, remembered on the device. On web, text size scales the whole page (zoom);
// native apps also follow the phone's own text-size setting.
// First visit, nothing chosen yet: start in the first of the device's preferred languages that FirePath
// has. Not saved, so a choice in Settings (which is saved) always wins.
export function deviceLanguage(preferred = typeof navigator !== 'undefined' && navigator.languages?.length ? navigator.languages : [Intl.DateTimeFormat().resolvedOptions().locale]) {
  for (const tag of preferred) { const base = String(tag).toLowerCase().split('-')[0]; if (dict[base]) return base; }
  return 'en';
}

export function I18nProvider({ children }) {
  const [lang, setLangState] = useState('en'), [scale, setScaleState] = useState(1);
  useEffect(() => {
    AsyncStorage.multiGet(['firepath-lang', 'firepath-scale']).then(([[, l], [, sc]]) => { setLangState(dict[l] ? l : deviceLanguage()); if (Number(sc)) setScaleState(Number(sc)); }).catch(() => {});
  }, []);
  useEffect(() => {
    // Korean wraps between words (keep-all), not mid-word.
    if (Platform.OS === 'web') { document.documentElement.lang = lang; document.body.style.zoom = String(scale); document.body.style.wordBreak = lang === 'ko' ? 'keep-all' : 'normal'; }
  }, [lang, scale]);
  const setLang = l => { setLangState(l); AsyncStorage.setItem('firepath-lang', l).catch(() => {}); };
  const setScale = sc => { setScaleState(sc); AsyncStorage.setItem('firepath-scale', String(sc)).catch(() => {}); };
  return <I18n.Provider value={{ lang, setLang, scale, setScale, t: (key, vars) => translate(lang, key, vars) }}>{children}</I18n.Provider>;
}

export const useI18n = () => useContext(I18n);
